// Test-only helpers around the THROWAWAY key fixtures in this directory.
//
// The JSON fixtures were generated by `ThresholdRSAKey` for the unit tests
// alone (see each file's `_comment`). They have never been used on any chain
// and must never be: all shares are committed so the tests can sign.
import crypto from "crypto";
import {
  RSASignatureShare,
  ThresholdRSAKey,
  ThresholdRSAShare,
  ThresholdRSAVerifier,
  ThresholdRSAVerifierConfig,
} from "../../src";

export type KeyFixture = {
  bits: number;
  threshold: number;
  numParties: number;
  publicKey: { n: string; e: string };
  sharedKey: {
    v: string;
    vku: string;
    shares: string[];
    verificationKeys: string[];
  };
};

export type GoldenVector = {
  message: string;
  messageEncoding: "hex" | "utf8";
  sha256: string;
  zeroNibble: boolean;
  lifted: boolean;
  partials: string[];
  combined: string;
  rawHashPartials?: string[];
  rawHashCombined?: string;
};

export type GoldenFile = {
  generatedBy: { package: string; version: string; commit: string };
  bits: number;
  threshold: number;
  numParties: number;
  keyFixture: string;
  vectors: GoldenVector[];
};

export function loadThrowawayKey(bits: 1024 | 4096): KeyFixture {
  return require(`./throwaway-key-${bits}-2of3.json`);
}

export function loadGolden(bits: 1024 | 4096): GoldenFile {
  return require(`./golden-1.3.0-${bits}.json`);
}

export function shareConfig(fx: KeyFixture, i: number) {
  return {
    bits: fx.bits,
    sharedKey: fx.sharedKey.shares[i],
    publicKey: fx.publicKey,
    verificationKey: fx.sharedKey.v,
    verificationKeyShare: fx.sharedKey.verificationKeys[i],
    vku: fx.sharedKey.vku,
  };
}

export function makeSigners(fx: KeyFixture): ThresholdRSAShare[] {
  return fx.sharedKey.shares.map(
    (_, i) => new ThresholdRSAShare(shareConfig(fx, i))
  );
}

export function verifierConfig(
  fx: KeyFixture,
  extra: Partial<ThresholdRSAVerifierConfig> = {}
): ThresholdRSAVerifierConfig {
  return {
    threshold: fx.threshold,
    numParties: fx.numParties,
    bits: fx.bits,
    publicKey: fx.publicKey,
    verificationKey: fx.sharedKey.v,
    vku: fx.sharedKey.vku,
    verificationKeys: fx.sharedKey.verificationKeys,
    ...extra,
  };
}

export function makeVerifier(
  fx: KeyFixture,
  extra: Partial<ThresholdRSAVerifierConfig> = {}
): ThresholdRSAVerifier {
  return new ThresholdRSAVerifier(verifierConfig(fx, extra));
}

// Build the share object a combiner receives for party `i` (0-based) over `message`.
// Mirrors the oracle: no proof, no prover-supplied verification key.
export function partialFor(
  signer: ThresholdRSAShare,
  i: number,
  message: Buffer | string
): RSASignatureShare {
  const r = signer.signMessage(message);
  return { signatureShare: r.signatureShare, shareIndex: i + 1 };
}

export function partialWithProofFor(
  signer: ThresholdRSAShare,
  i: number,
  hashHex: string,
  pkcs1 = true
): RSASignatureShare {
  const r = signer.signHash(hashHex, { pkcs1, proof: true });
  return {
    signatureShare: r.signatureShare,
    proof: r.proof,
    shareIndex: i + 1,
  };
}

export function decodeMessage(v: GoldenVector): Buffer | string {
  return v.messageEncoding === "hex"
    ? Buffer.from(v.message, "hex")
    : v.message;
}

// Fresh throwaway key generated inside the test process (fast at 1024 bits).
export async function generateThrowawayKey(
  bits: number,
  threshold: number,
  numParties: number
) {
  const key = new ThresholdRSAKey({ bits });
  await key.generateKeyPair();
  const split = key.splitShares(threshold, numParties);
  const fixture: KeyFixture = {
    bits,
    threshold,
    numParties,
    publicKey: {
      n: split.publicKey.n.toString(16),
      e: split.publicKey.e.toString(16),
    },
    sharedKey: {
      v: split.sharedKey.v.toString(16),
      vku: split.sharedKey.vku.toString(16),
      shares: split.sharedKey.shares.map((s) => s.toString(16)),
      verificationKeys: split.sharedKey.verificationKeys.map((s) =>
        s.toString(16)
      ),
    },
  };
  return { key, split, fixture };
}

// Independent PKCS#1 v1.5 verification through OpenSSL (node:crypto).
export function opensslVerify(
  fx: KeyFixture,
  message: Buffer | string,
  signatureHex: string
): boolean {
  const b64u = (hex: string) => Buffer.from(hex, "hex").toString("base64url");
  const eHex =
    fx.publicKey.e.length % 2 ? "0" + fx.publicKey.e : fx.publicKey.e;
  const nHex =
    fx.publicKey.n.length % 2 ? "0" + fx.publicKey.n : fx.publicKey.n;
  const pub = crypto.createPublicKey({
    key: { kty: "RSA", n: b64u(nHex), e: b64u(eHex) },
    format: "jwk",
  });
  return crypto.verify(
    "sha256",
    Buffer.isBuffer(message) ? message : Buffer.from(message, "utf8"),
    { key: pub, padding: crypto.constants.RSA_PKCS1_PADDING },
    Buffer.from(signatureHex, "hex")
  );
}

export function randomHashHex(
  predicate: (h: string) => boolean = () => true
): string {
  let h: string;
  do {
    h = crypto.randomBytes(32).toString("hex");
  } while (!predicate(h));
  return h;
}
